	hostent *entry;
	in_addr *node;

	if (isdigit(ip[0]))
		return ( Bind( ntohl(inet_addr(ip)), port) );

	strcpy(host, ip);

	entry = gethostbyname(ip);
	if (entry == NULL)
		return (0);
